import pandas as pd
import numpy as np

# Load the data
df = pd.read_csv('chunks_csv/changespillover/changespillover_2021_2023_energy.csv')
adjacency_path = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Calculate the change in Energy
df['Energy_change'] = df['Energy_2023'] - df['Energy_2021']

# Identify neighboring boroughs
adjacency = adjacency_path.set_index('borough').T.to_dict('list')
neighborhoods = {}
for borough, neighbors in adjacency.items():
    neighborhoods[borough] = neighbors

# Compute the change in Energy for neighboring boroughs
neighbor_changes = {}
for borough, neighbors in neighborhoods.items():
    neighbor_changes[borough] = []
    for neighbor in neighbors:
        neighbor_changes[borough].append(df.loc[df['borough'] == neighbor, 'Energy_change'].iloc[0])

# Calculate the direction of change
direction = {}
for borough in df['borough']:
    if df.loc[df['borough'] == borough, 'Energy_change'].iloc[0] > 0:
        direction[borough] = 1
    else:
        direction[borough] = -1

# Calculate the similarity of change
similarity = {}
for borough in df['borough']:
    similarity[borough] = 0
    for neighbor in neighborhoods[borough]:
        similarity[borough] += direction[neighbor] * direction[borough]
    similarity[borough] /= len(neighborhoods[borough])

# Apply Global Moran's I
n = len(df)
W = 0
for borough in df['borough']:
    W += 1 / len(neighborhoods[borough])
W /= n
S = 0
for borough in df['borough']:
    S += similarity[borough]
S /= n
I = (n * sum([similarity[borough] * (1 - similarity[borough]) for borough in df['borough']]) - S) / (1 - W)
data_points_used = n

# Permutation test
p_values = []
for _ in range(500):
    np.random.shuffle(df['Energy_change'])
    I_perm = (n * sum([similarity[borough] * (1 - similarity[borough]) for borough in df['borough']]) - S) / (1 - W)
    p_values.append(I_perm)

# Determine clustering
p_value = np.mean([1 for i in p_values if i >= I])
if p_value < 0.05:
    print(f"FINAL ANSWER: CLUSTERED (test statistic = {I}, p = {p_value})")
else:
    print(f"FINAL ANSWER: NOT CLUSTERED (test statistic = {I}, p = {p_value})")
